-- Q22 [Cell Potential & Equilibrium · medium · Skill 2 · 4C Electrochemistry (GC) · ans D] (g64)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Potential & Equilibrium',
    $qt64$A spontaneous galvanic cell is built on a two-electron redox reaction \((n = 2)\) whose equilibrium constant at 298 K is \(K_{eq} = 1.0 \times 10^{10}\). Using the relationship \(\Delta G^{\circ} = -nFE^{\circ}_{\text{cell}} = -RT\ln K_{eq}\), which at 298 K reduces to \(E^{\circ}_{\text{cell}} = \frac{0.0592}{n}\log K_{eq}\), what is the standard cell potential \(E^{\circ}_{\text{cell}}\) for the reaction as written?$qt64$,
    $op64$[{"label":"A","text":"\\(-0.296\\ \\text{V}\\)"},{"label":"B","text":"\\(+0.592\\ \\text{V}\\)"},{"label":"C","text":"\\(+0.682\\ \\text{V}\\)"},{"label":"D","text":"\\(+0.296\\ \\text{V}\\)"}]$op64$::jsonb,
    'D',
    $ex64$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is D because the standard cell potential is obtained directly from \(E^{\circ}_{\text{cell}} = \frac{0.0592}{n}\log K_{eq}\) at 298 K. Substituting \(n = 2\) and \(K_{eq} = 1.0 \times 10^{10}\): the logarithm of \(1.0 \times 10^{10}\) is \(\log(1.0 \times 10^{10}) = 10\). Then \(E^{\circ}_{\text{cell}} = \frac{0.0592}{2}\times 10 = 0.0296 \times 10 = +0.296\ \text{V}\). The result is positive, consistent with \(K_{eq} > 1\) (products favored), which corresponds to \(\Delta G^{\circ} < 0\) and a spontaneous galvanic cell. (Choice A) \(-0.296\ \text{V}\) has the correct magnitude but the wrong sign; a \(K_{eq} > 1\) gives a positive \(\log K_{eq}\) and therefore a positive \(E^{\circ}_{\text{cell}}\), and a galvanic cell with products favored at equilibrium must have \(E^{\circ}_{\text{cell}} > 0\). (Choice B) \(+0.592\ \text{V}\) results from omitting the division by \(n\), i.e. computing \(0.0592 \times \log K_{eq} = 0.0592 \times 10\); the factor \(n = 2\) must divide the \(0.0592\) term. (Choice C) \(+0.682\ \text{V}\) results from using the natural logarithm of \(K_{eq}\) (\(\ln(1.0\times10^{10}) \approx 23.0\)) inside the base-10 form, i.e. \(\frac{0.0592}{2}\times 23.0\); the \(0.0592\) prefactor is paired with \(\log_{10}\), not \(\ln\) (the \(\ln\) form carries the prefactor \(\frac{RT}{nF} \approx \frac{0.0257}{n}\) instead). Skill 2$ex64$,
    'medium', '4C', $cc64$Electrochemistry (GC)$cc64$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
